import { Button } from "../Button";
import { StyleFn } from "..";

export const Calendar: StyleFn = (theme, mode) => {
  const { color, font, opacity, size } = theme;
  const { root: buttonBase, _ghost, _medium } = Button(theme, mode);

  const colors = {
    text: color.text.neutral.strong[mode],
    selectedText: color.text.neutral.minimal[mode],
    selectedBG: color.surface.accent.default[mode],
    selectedHover: color.surface.accent.hover[mode],
    accent: color.text.accent.corporate[mode],
    range: color.surface.interaction.hover[mode],
  };

  return {
    root: {
      display: "inline-block",
      position: "relative",
      minWidth: "18.5rem",
      minHeight: "18.5rem",
      color: colors.text,
      fontWeight: font.weight.medium,
    },
    navbar: {
      display: "flex",
      position: "absolute",
      left: 0,
      right: 0,
      maxWidth: "18.5rem",
      justifyContent: "space-between",
      padding: size.spacing[8],
    },
    navbar_select: {
      width: size.spacing[96],
    },
    months: {
      display: "flex",
      flexWrap: "wrap",
      justifyContent: "center",
    },
    month: {
      marginTop: size.spacing[8],
      padding: `${size.spacing[8]}`,
      width: "18.5rem",
      // @see https://css-tricks.com/fighting-the-space-between-inline-block-elements/
      fontSize: 0,
      textAlign: "center"
    },
    month_today: {
      "& $caption": {
        color: colors.accent,
      },
    },
    caption: {
      height: size.spacing[20],
      marginBottom: size.spacing[8],
      textAlign: "center",
      fontSize: font.size.medium,
    },
    weekday: {
      display: "inline-block",
      width: "calc(100% / 7)",
      padding: `${size.spacing[16]} ${size.spacing[4]}`,
      fontSize: font.size.small,
      textAlign: "center",
    },
    day: {
      extend: [buttonBase, _ghost, _medium],
      width: "calc(100% / 7)",
      borderRadius: 0,
      color: colors.text,
      fontWeight: font.weight.medium,
      "&:focus-visible": {
        border: "2px solid #fff", //
        borderRadius: size.spacing[4], //
        "&:after": {
          zIndex: 1, //to keep focus ring always on top
        },
      }
    },
    day_outside: {
      opacity: opacity.disabled,
    },
    day_today: {
      border: `1px solid ${colors.accent}`,
      borderRadius: 3,
      color: colors.accent,
      position: "relative",
      "&:before": {
        position: "absolute",
        content: "''",
        width: size.spacing[4],
        height: size.spacing[4],
        bottom: size.spacing[4],
        backgroundColor: colors.accent,
        borderRadius: "50%",
      }
    },
    day_selected: {
      borderRadius: 3,
      backgroundColor: colors.selectedBG,
      color: colors.selectedText,
      "&[aria-pressed='true']": {
        backgroundColor: colors.accent,
      },
      "&:hover, &:active": {
        backgroundColor: colors.selectedHover,
      },
      "&:focus": { //extra space
        borderColor: "2px solid #fff"
      },
    },
    day_range: {
      backgroundColor: colors.range,
    },
  };
};
